import re, pathlib
root = pathlib.Path('my_website')
pages = ['index.html','blog.html','publications.html']
# collect ids per page
ids_by_page = {}
for p in pages:
    txt = root.joinpath(p).read_text()
    ids = set(re.findall(r'\sid="([^"]+)"', txt))
    ids_by_page[p] = ids

broken = []
href_hash_count = 0
checked = 0
attr_pat = re.compile(r'(href|src)="([^"]+)"')
for p in pages:
    txt = root.joinpath(p).read_text()
    for m in attr_pat.finditer(txt):
        attr, url = m.group(1), m.group(2)
        checked += 1
        # skip schemes
        if re.match(r'^(https?:|mailto:|data:|#)', url):
            if url == '#':
                href_hash_count += 1
            # fragment only
            if url.startswith('#'):
                frag = url[1:]
                if frag not in ids_by_page[p]:
                    broken.append((p, url, 'fragment missing in same page'))
            # cross-page fragment? url like file.html#frag
            elif '#' in url:
                # split
                path, frag = url.split('#',1)
                # resolve path relative to current page
                target = pathlib.Path(path)
                if not target.name:
                    target = pathlib.Path(p)
                # if path is empty? already handled
                # normalize
                # we need to find target page name
                # if path is relative, resolve
                # For simplicity, assume path is filename in same dir
                target_name = target.name if target.name else p
                # if target_name not in pages, maybe it's an asset
                if target_name in ids_by_page:
                    if frag not in ids_by_page[target_name]:
                        broken.append((p, url, f'fragment {frag} missing in {target_name}'))
                else:
                    # treat as file existence
                    if not (root / target_name).exists():
                        broken.append((p, url, 'file missing'))
            continue
        # else relative file
        # handle fragment
        if '#' in url:
            path, frag = url.split('#',1)
        else:
            path, frag = url, None
        # resolve path relative to my_website
        # if path starts with ./ or /
        # assume relative to root
        target_path = root / path
        if not target_path.exists():
            broken.append((p, url, 'file missing'))
        else:
            # if fragment, check id in target page if it's html
            if frag:
                # find target page name
                if target_path.suffix in ('.html',):
                    target_name = target_path.name
                    if target_name in ids_by_page:
                        if frag not in ids_by_page[target_name]:
                            broken.append((p, url, f'fragment {frag} missing in {target_name}'))
                    else:
                        broken.append((p, url, 'target page not indexed'))
                else:
                    # non-html file, fragment irrelevant? ignore
                    pass

print(f'N links checked: {checked}')
print(f'href="#" occurrences: {href_hash_count}')
if broken:
    print('Broken links:')
    for b in broken:
        print(b)
else:
    print('0 broken')
